#!/usr/bin/env node
// Generated by BootAgent. Do not edit: BootAgent rewrites this Skill when its
// model or Provider changes.
//
// Calls one multimodal model on the user's own Provider. Node 18 or later, no
// dependencies. The API key comes from the environment variable named in
// config.json, or from BootAgent's private fallback file; it is never printed.

import { execFile } from "node:child_process";
import { accessSync, constants, createWriteStream, existsSync, linkSync, mkdirSync, mkdtempSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { basename, delimiter, dirname, extname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";

const EXIT = { ok: 0, internal: 1, usage: 2, setup: 3, refused: 4, key: 5, unavailable: 6, pending: 7 };
const MiB = 1024 * 1024;
const LIMITS = { image: 20 * MiB, audio: 25 * MiB, download: 50 * MiB, speech: 50 * MiB, video: 2048 * MiB, response: 100 * MiB };

class Failure extends Error {
  constructor(code, message) {
    super(message);
    this.code = code;
  }
}

let secret = "";

// The key never reaches output, even when a provider echoes the request back.
function redact(text) {
  let value = String(text ?? "");
  if (secret) value = value.split(secret).join("[redacted]");
  return value.replace(/Bearer\s+[^\s"']+/g, "Bearer [redacted]");
}

function fail(code, message) {
  throw new Failure(code, message);
}

const here = dirname(fileURLToPath(import.meta.url));

function loadConfig() {
  const path = join(here, "..", "config.json");
  let config;
  try {
    config = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    fail(EXIT.setup, "config.json next to this Skill is missing or invalid. Reinstall the Skill from BootAgent.");
  }
  for (const field of ["capability", "adapter", "model", "base_url", "key_env"]) {
    if (typeof config[field] !== "string" || !config[field]) fail(EXIT.setup, `config.json has no ${field}. Reinstall the Skill from BootAgent.`);
  }
  if (!/^https?:\/\//.test(config.base_url)) fail(EXIT.setup, "config.json has an invalid base_url. Reinstall the Skill from BootAgent.");
  if (NATIVE.has(config.adapter) && !/^https:\/\/[^/]+$/.test(config.native_base_url ?? "")) {
    fail(EXIT.setup, "config.json has no native_base_url. Reinstall the Skill from BootAgent.");
  }
  return config;
}

function expandHome(path) {
  if (path === "~") return homedir();
  if (path.startsWith("~/") || path.startsWith("~\\")) return join(homedir(), path.slice(2));
  return path;
}

// Same quoting BootAgent writes: bare, or single-quoted with \' and \\.
function parseEnvFile(text, name) {
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const eq = line.indexOf("=");
    if (eq < 0 || line.slice(0, eq).trim() !== name) continue;
    let value = line.slice(eq + 1).trim();
    if (value.length >= 2 && value.startsWith("'") && value.endsWith("'")) {
      value = value.slice(1, -1).replace(/\\(['\\])/g, "$1");
    } else if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) {
      value = value.slice(1, -1).replace(/\\(["\\])/g, "$1");
    }
    return value;
  }
  return "";
}

function loadKey(config) {
  let key = process.env[config.key_env] ?? "";
  if (!key && typeof config.key_file === "string" && config.key_file) {
    const path = expandHome(config.key_file);
    if (existsSync(path)) {
      try {
        key = parseEnvFile(readFileSync(path, "utf8"), config.key_env);
      } catch {
        key = "";
      }
    }
  }
  key = key.trim();
  if (!key) {
    fail(EXIT.setup, `No API key found in ${config.key_env}. Restart the Agent so it picks up the variable BootAgent wrote, or reinstall the Skill from BootAgent.`);
  }
  secret = key;
  return key;
}

// Flags that may be given more than once collect into a list.
const REPEATED = new Set(["image", "form", "file", "query", "header"]);

function parseArgs(argv) {
  const options = { _: [] };
  for (let index = 0; index < argv.length; index++) {
    const arg = argv[index];
    if (!arg.startsWith("--")) {
      options._.push(arg);
      continue;
    }
    const name = arg.slice(2);
    if (name === "help") {
      options.help = true;
      continue;
    }
    const value = argv[index + 1];
    if (value === undefined || value.startsWith("--")) fail(EXIT.usage, `--${name} needs a value.`);
    index++;
    if (REPEATED.has(name)) (options[name] ??= []).push(value);
    else options[name] = value;
  }
  return options;
}

function positiveInt(value, name, fallback, max) {
  if (value === undefined) return fallback;
  const number = Number(value);
  if (!Number.isInteger(number) || number < 1 || number > max) fail(EXIT.usage, `--${name} must be a whole number from 1 to ${max}.`);
  return number;
}

function readInput(path, limit, kind) {
  const full = resolve(path);
  let info;
  try {
    info = statSync(full);
  } catch {
    fail(EXIT.usage, `${kind} file not found: ${path}`);
  }
  if (!info.isFile()) fail(EXIT.usage, `${kind} path is not a file: ${path}`);
  if (info.size > limit) fail(EXIT.usage, `${kind} file is larger than ${Math.round(limit / MiB)} MB: ${path}`);
  return readFileSync(full);
}

const IMAGE_TYPES = { ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".gif": "image/gif" };

function stamp() {
  return new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
}

// Linking a completed temporary file publishes it atomically and refuses an
// existing destination. Concurrent runs retry with a suffix instead of
// checking first and then accidentally replacing another run's output.
function publishOutput(partial, path) {
  const extension = extname(path);
  const stem = path.slice(0, path.length - extension.length);
  for (let counter = 1; ; counter++) {
    const candidate = counter === 1 ? path : `${stem}-${counter}${extension}`;
    try {
      linkSync(partial, candidate);
      return candidate;
    } catch (error) {
      if (error?.code !== "EEXIST") {
        fail(EXIT.unavailable, `Cannot save the result without overwriting an existing file (${error?.code ?? "filesystem error"}). Choose an output directory on a filesystem that supports hard links.`);
      }
    }
  }
}

function writeOutput(path, data) {
  const target = resolve(path);
  mkdirSync(dirname(target), { recursive: true });
  const work = mkdtempSync(join(dirname(target), ".bootagent-output-"));
  try {
    const partial = join(work, "result.part");
    writeFileSync(partial, data, { mode: 0o600, flag: "wx" });
    return publishOutput(partial, target);
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

function outputDirectory(config, options) {
  return resolve(options.out || expandHome(config.output_dir || "~/.bootagent/output"));
}

function detail(text) {
  let message = text;
  try {
    const parsed = JSON.parse(text);
    const error = parsed?.error;
    message = (typeof error === "string" && error) || error?.message || parsed?.message || parsed?.detail || text;
  } catch {
    // Not JSON; keep the text.
  }
  message = redact(String(message)).replace(/\s+/g, " ").trim();
  if (/^</.test(message)) return "";
  return message.length > 400 ? `${message.slice(0, 400)}…` : message;
}

const NATIVE = new Set(["novita-audio", "novita-async"]);

// base picks the OpenAI-compatible route or the Provider's host root.
async function call(config, key, path, init, timeoutMs, base = config.base_url) {
  const url = base.replace(/\/+$/, "") + path;
  let response;
  try {
    response = await fetch(url, {
      ...init,
      headers: { ...(init.headers ?? {}), Authorization: `Bearer ${key}` },
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch (error) {
    if (error?.name === "TimeoutError" || error?.name === "AbortError") fail(EXIT.unavailable, `The provider did not answer within ${Math.round(timeoutMs / 1000)} s.`);
    fail(EXIT.unavailable, `Cannot reach the provider: ${redact(error?.cause?.code ?? error?.message ?? error)}`);
  }
  if (response.ok) return response;
  const said = detail(await response.text().catch(() => ""));
  const suffix = said ? `: ${said}` : ".";
  if (response.status === 401 || response.status === 403) fail(EXIT.key, `The provider rejected the API key (HTTP ${response.status})${suffix}`);
  if (response.status === 408 || response.status === 429 || response.status >= 500) fail(EXIT.unavailable, `The provider is busy or failing (HTTP ${response.status})${suffix}`);
  fail(EXIT.refused, `The provider refused the request (HTTP ${response.status})${suffix}`);
}

async function json(response) {
  try {
    return await response.json();
  } catch {
    fail(EXIT.unavailable, "The provider returned a response that is not JSON.");
  }
}

// Result URLs are pre-signed and may be on another host, so the key is not
// sent with them.
async function download(url, timeoutMs) {
  let response;
  try {
    response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
  } catch {
    fail(EXIT.unavailable, "Cannot download the result from the provider.");
  }
  if (!response.ok) fail(EXIT.unavailable, `Cannot download the result (HTTP ${response.status}).`);
  const data = Buffer.from(await response.arrayBuffer());
  if (data.length > LIMITS.download) fail(EXIT.unavailable, "The result is larger than expected and was not saved.");
  return data;
}

function imageExtension(data) {
  if (data.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return ".png";
  if (data[0] === 0xff && data[1] === 0xd8) return ".jpg";
  if (data.subarray(0, 4).toString("latin1") === "RIFF" && data.subarray(8, 12).toString("latin1") === "WEBP") return ".webp";
  if (data.subarray(0, 3).toString("latin1") === "GIF") return ".gif";
  return ".png";
}

async function describe(config, key, options, timeoutMs) {
  const images = options.image ?? [];
  if (!images.length) fail(EXIT.usage, "Give at least one --image.");
  if (images.length > 8) fail(EXIT.usage, "Give at most 8 images.");
  const content = [{ type: "text", text: options.prompt || "Describe this image." }];
  for (const path of images) {
    const type = IMAGE_TYPES[extname(path).toLowerCase()];
    if (!type) fail(EXIT.usage, `Unsupported image type: ${path} (use PNG, JPEG, WebP or GIF).`);
    const data = readInput(path, LIMITS.image, "Image");
    content.push({ type: "image_url", image_url: { url: `data:${type};base64,${data.toString("base64")}` } });
  }
  const response = await call(config, key, "/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: config.model,
      messages: [{ role: "user", content }],
      max_tokens: positiveInt(options["max-tokens"], "max-tokens", 1024, 32768),
    }),
  }, timeoutMs);
  const body = await json(response);
  const text = body?.choices?.[0]?.message?.content;
  const answer = Array.isArray(text) ? text.map((part) => part?.text ?? "").join("") : text;
  if (typeof answer !== "string") fail(EXIT.unavailable, "The provider returned no text.");
  process.stdout.write(redact(answer.trim()) + "\n");
}

async function generate(config, key, options, timeoutMs) {
  if (!options.prompt) fail(EXIT.usage, "Give a --prompt.");
  const count = positiveInt(options.n, "n", 1, 4);
  const request = { model: config.model, prompt: options.prompt, n: count };
  if (options.size) request.size = options.size;
  const response = await call(config, key, "/images/generations", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(request),
  }, timeoutMs);
  const body = await json(response);
  const items = Array.isArray(body?.data) ? body.data : [];
  if (!items.length) fail(EXIT.unavailable, "The provider returned no image.");
  const directory = outputDirectory(config, options);
  const base = `image-${stamp()}`;
  const saved = [];
  for (const [index, item] of items.entries()) {
    let data;
    if (typeof item?.b64_json === "string") data = Buffer.from(item.b64_json, "base64");
    else if (typeof item?.url === "string") data = await download(item.url, timeoutMs);
    else continue;
    const name = items.length > 1 ? `${base}-${index + 1}` : base;
    saved.push(writeOutput(join(directory, name + imageExtension(data)), data));
  }
  if (!saved.length) fail(EXIT.unavailable, "The provider returned no image data.");
  process.stdout.write(saved.join("\n") + "\n");
}

async function transcribe(config, key, options, timeoutMs) {
  if (!options.audio) fail(EXIT.usage, "Give an --audio file.");
  const data = readInput(options.audio, LIMITS.audio, "Audio");
  const form = new FormData();
  form.append("model", config.model);
  form.append("file", new Blob([data]), basename(options.audio));
  if (options.language) form.append("language", options.language);
  if (options.prompt) form.append("prompt", options.prompt);
  const response = await call(config, key, "/audio/transcriptions", { method: "POST", body: form }, timeoutMs);
  const body = await json(response);
  if (typeof body?.text !== "string") fail(EXIT.unavailable, "The provider returned no transcript.");
  process.stdout.write(redact(body.text.trim()) + "\n");
}

const SPEECH_FORMATS = ["mp3", "wav", "opus", "aac", "flac", "pcm"];

async function speak(config, key, options, timeoutMs) {
  if (!options.text) fail(EXIT.usage, "Give the --text to speak.");
  if (options.text.length > 4096) fail(EXIT.usage, "--text is longer than 4096 characters; split it.");
  const format = (options.format || "mp3").toLowerCase();
  if (!SPEECH_FORMATS.includes(format)) fail(EXIT.usage, `--format must be one of ${SPEECH_FORMATS.join(", ")}.`);
  const response = await call(config, key, "/audio/speech", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: config.model, input: options.text, voice: options.voice || "alloy", response_format: format }),
  }, timeoutMs);
  const data = Buffer.from(await response.arrayBuffer());
  if (!data.length) fail(EXIT.unavailable, "The provider returned no audio.");
  if (data.length > LIMITS.speech) fail(EXIT.unavailable, "The audio is larger than expected and was not saved.");
  const target = options.out && extname(options.out)
    ? options.out
    : join(outputDirectory(config, options), `speech-${stamp()}.${format}`);
  process.stdout.write(writeOutput(target, data) + "\n");
}

// MiniMax-style routes answer HTTP 200 for some refusals and carry the
// verdict in base_resp.status_code.
function checkBaseResp(body) {
  const code = body?.base_resp?.status_code;
  if (code === undefined || code === 0) return;
  const said = detail(JSON.stringify({ message: body?.base_resp?.status_msg ?? "" }));
  const suffix = said ? `: ${said}` : ".";
  if (code === 1004) fail(EXIT.key, `The provider rejected the API key (${code})${suffix}`);
  if (code === 1002 || code === 1039) fail(EXIT.unavailable, `The provider is rate limiting (${code})${suffix}`);
  if (code === 1000 || code === 1001) fail(EXIT.unavailable, `The provider failed (${code})${suffix}`);
  fail(EXIT.refused, `The provider refused the request (${code})${suffix}`);
}

const NATIVE_SPEECH_FORMATS = ["mp3", "wav", "flac", "pcm"];

async function speakNative(config, key, options, timeoutMs) {
  if (!options.text) fail(EXIT.usage, "Give the --text to speak.");
  if (options.text.length > 9999) fail(EXIT.usage, "--text is longer than 9999 characters; split it.");
  const format = (options.format || "mp3").toLowerCase();
  if (!NATIVE_SPEECH_FORMATS.includes(format)) fail(EXIT.usage, `--format must be one of ${NATIVE_SPEECH_FORMATS.join(", ")}.`);
  const voice = { voice_id: options.voice || "English_Graceful_Lady" };
  if (options.speed !== undefined) {
    const speed = Number(options.speed);
    if (!(speed >= 0.5 && speed <= 2)) fail(EXIT.usage, "--speed must be from 0.5 to 2.");
    voice.speed = speed;
  }
  const response = await call(config, key, `/v3/${encodeURIComponent(config.model)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text: options.text, voice_setting: voice, audio_setting: { format }, output_format: "hex" }),
  }, timeoutMs, config.native_base_url);
  const body = await json(response);
  checkBaseResp(body);
  const hex = body?.data?.audio;
  if (typeof hex !== "string" || !hex || !/^[0-9a-fA-F]+$/.test(hex) || hex.length % 2) fail(EXIT.unavailable, "The provider returned no audio.");
  const data = Buffer.from(hex, "hex");
  if (data.length > LIMITS.speech) fail(EXIT.unavailable, "The audio is larger than expected and was not saved.");
  const target = options.out && extname(options.out)
    ? options.out
    : join(outputDirectory(config, options), `speech-${stamp()}.${format}`);
  process.stdout.write(writeOutput(target, data) + "\n");
}

const VIDEO_FLAGS = { duration: "duration", size: "size", "aspect-ratio": "aspect_ratio", "negative-prompt": "negative_prompt", sound: "sound" };

async function generateVideo(config, key, options, timeoutMs) {
  if (!options.prompt) fail(EXIT.usage, "Give a --prompt.");
  const allowed = new Set(config.options ?? []);
  const request = { prompt: options.prompt };
  for (const [flag, field] of Object.entries(VIDEO_FLAGS)) {
    if (options[flag] === undefined) continue;
    if (!allowed.has(field)) fail(EXIT.usage, `${config.model} does not take --${flag}.`);
    if (field === "duration") request.duration = positiveInt(options[flag], flag, 5, 60);
    else if (field === "sound") {
      if (options[flag] !== "true" && options[flag] !== "false") fail(EXIT.usage, "--sound must be true or false.");
      request.sound = options[flag] === "true";
    } else request[field] = options[flag];
  }
  for (const flag of Object.keys(options)) {
    if (!["_", "prompt", "out", "timeout", ...Object.keys(VIDEO_FLAGS)].includes(flag)) fail(EXIT.usage, `Unknown option --${flag}.`);
  }
  const deadline = Date.now() + timeoutMs;
  const response = await call(config, key, `/v3/async/${encodeURIComponent(config.model)}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(request),
  }, Math.min(timeoutMs, 60000), config.native_base_url);
  const body = await json(response);
  const task = body?.task_id;
  if (typeof task !== "string" || !task) fail(EXIT.unavailable, "The provider returned no task id.");
  process.stderr.write(redact(`task: ${task}\n`));
  await finishVideo(config, key, task, options, deadline);
}

async function videoResult(config, key, options, timeoutMs) {
  if (!options.task || !/^[A-Za-z0-9._-]{1,128}$/.test(options.task)) fail(EXIT.usage, "Give the --task id the video command printed.");
  await finishVideo(config, key, options.task, options, Date.now() + timeoutMs);
}

const sleep = (ms) => new Promise((done) => setTimeout(done, ms));

// Polls the task until it settles or the deadline passes. A busy or briefly
// unreachable provider is polled again; a refusal or a failed task is final,
// because retrying a generation spends money.
async function finishVideo(config, key, task, options, deadline) {
  let delay = 5000;
  for (;;) {
    let body;
    try {
      const response = await call(config, key, `/v3/async/task-result?task_id=${encodeURIComponent(task)}`, { method: "GET" }, 30000, config.native_base_url);
      body = await json(response);
    } catch (error) {
      if (!(error instanceof Failure) || error.code !== EXIT.unavailable) throw error;
    }
    const status = body?.task?.status;
    if (status === "TASK_STATUS_SUCCEED") {
      const videos = Array.isArray(body?.videos) ? body.videos.filter((item) => typeof item?.video_url === "string") : [];
      if (!videos.length) fail(EXIT.unavailable, `Task ${task} finished without a video.`);
      const directory = outputDirectory(config, options);
      const saved = [];
      for (const [index, item] of videos.entries()) {
        const extension = item.video_type === "gif" ? "gif" : "mp4";
        const name = `video-${stamp()}${videos.length > 1 ? `-${index + 1}` : ""}.${extension}`;
        saved.push(await downloadTo(item.video_url, join(directory, name), Math.max(deadline - Date.now(), 120000)));
      }
      process.stdout.write(saved.join("\n") + "\n");
      return;
    }
    if (status === "TASK_STATUS_FAILED") {
      const reason = redact(String(body?.task?.reason ?? "")).slice(0, 400);
      fail(EXIT.refused, `Task ${task} failed${reason ? `: ${reason}` : "."}`);
    }
    // The provider's eta paces the next poll when it gives one; otherwise
    // back off from 5 s to 15 s.
    const eta = Number(body?.task?.eta);
    const wait = Number.isFinite(eta) && eta > 0 ? Math.min(Math.max(eta * 1000, 1000), 15000) : delay;
    if (Date.now() + wait > deadline) {
      fail(EXIT.pending, `Task ${task} has not finished yet. It may still finish and be billed; fetch it later with: video-result --task ${task}`);
    }
    await sleep(wait);
    delay = Math.min(delay + 5000, 15000);
  }
}

// Streams a result to disk, so a large video is never held in memory, and
// removes the partial file on failure. The URL is pre-signed and may be on
// another host, so the key is not sent.
async function downloadTo(url, path, timeoutMs) {
  let response;
  try {
    response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
  } catch {
    fail(EXIT.unavailable, "Cannot download the result from the provider.");
  }
  if (!response.ok || !response.body) fail(EXIT.unavailable, `Cannot download the result (HTTP ${response.status}).`);
  return saveStream(response.body, path, LIMITS.video);
}

async function saveStream(body, path, limit) {
  const target = resolve(path);
  mkdirSync(dirname(target), { recursive: true });
  const work = mkdtempSync(join(dirname(target), ".bootagent-output-"));
  const partial = join(work, "result.part");
  let size = 0;
  try {
    await pipeline(Readable.fromWeb(body), async function* (chunks) {
      for await (const chunk of chunks) {
        size += chunk.length;
        if (size > limit) throw new Failure(EXIT.unavailable, "The result is larger than expected and was not saved.");
        yield chunk;
      }
    }, createWriteStream(partial, { mode: 0o600, flags: "wx" }));
    return publishOutput(partial, target);
  } catch (error) {
    if (error instanceof Failure) throw error;
    fail(EXIT.unavailable, "The download was interrupted.");
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

// Each capability and adapter this script implements: the subcommand, its
// handler and default timeout in seconds, plus any extra subcommands.
// findExecutable looks a command up on PATH the way a shell would.
function findExecutable(name) {
  const names = process.platform === "win32" ? [`${name}.exe`, `${name}.cmd`, name] : [name];
  for (const directory of (process.env.PATH ?? "").split(delimiter)) {
    if (!directory) continue;
    for (const candidate of names) {
      const path = join(directory, candidate);
      try {
        accessSync(path, constants.X_OK);
        if (statSync(path).isFile()) return path;
      } catch {
        // Not here.
      }
    }
  }
  return "";
}

// runTool runs a helper with an argv array, a timeout, and an environment of
// PATH alone: the child never sees the API key.
function runTool(file, args, timeoutMs) {
  const env = { PATH: process.env.PATH ?? "" };
  if (process.env.SystemRoot) env.SystemRoot = process.env.SystemRoot;
  return new Promise((done) => {
    execFile(file, args, { env, timeout: timeoutMs, maxBuffer: 4 * MiB, windowsHide: true }, (error, stdout, stderr) => {
      done({ code: error ? (typeof error.code === "number" ? error.code : -1) : 0, stderr: String(stderr ?? "") });
    });
  });
}

async function videoDuration(ffmpeg, path) {
  // ffmpeg with an input and no output prints the input's details, then
  // exits non-zero; the duration line is what is wanted.
  const { stderr } = await runTool(ffmpeg, ["-hide_banner", "-i", path], 30000);
  const match = /Duration:\s*(\d+):(\d{2}):(\d{2}(?:\.\d+)?)/.exec(stderr);
  return match ? Number(match[1]) * 3600 + Number(match[2]) * 60 + Number(match[3]) : 0;
}

async function describeVideo(config, key, options, timeoutMs) {
  if (!options.video) fail(EXIT.usage, "Give a --video file.");
  const path = resolve(options.video);
  let info;
  try {
    info = statSync(path);
  } catch {
    fail(EXIT.usage, `Video file not found: ${options.video}`);
  }
  if (!info.isFile()) fail(EXIT.usage, `Video path is not a file: ${options.video}`);
  const count = positiveInt(options.frames, "frames", 8, 16);
  const ffmpeg = findExecutable("ffmpeg");
  if (!ffmpeg) fail(EXIT.setup, "ffmpeg was not found on PATH. Install ffmpeg to describe videos.");
  const duration = await videoDuration(ffmpeg, path);
  const work = mkdtempSync(join(tmpdir(), "bootagent-frames-"));
  try {
    const frames = [];
    for (let index = 0; index < count; index++) {
      // Evenly spaced, at the middle of each slice; without a duration, one
      // frame a second from the start.
      const at = duration > 0 ? Math.min((duration / count) * (index + 0.5), Math.max(duration - 0.05, 0)) : index;
      const out = join(work, `frame-${index}.jpg`);
      await runTool(ffmpeg, ["-hide_banner", "-loglevel", "error", "-ss", at.toFixed(2), "-i", path, "-frames:v", "1", "-vf", "scale='min(1024,iw)':-2", "-q:v", "4", "-y", out], 60000);
      if (existsSync(out) && statSync(out).size > 0) frames.push({ at, data: readFileSync(out) });
    }
    if (!frames.length) fail(EXIT.usage, `No frames could be read from ${options.video}.`);
    const when = frames.map((frame) => `${frame.at.toFixed(1)} s`).join(", ");
    const preface = `${options.prompt || "Describe what happens in this video."}\n\nThe images are ${frames.length} frames sampled in order from a${duration > 0 ? ` ${duration.toFixed(1)} s` : ""} video, at ${when}.`;
    const content = [{ type: "text", text: preface }, ...frames.map((frame) => ({ type: "image_url", image_url: { url: `data:image/jpeg;base64,${frame.data.toString("base64")}` } }))];
    const response = await call(config, key, "/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model: config.model, messages: [{ role: "user", content }], max_tokens: positiveInt(options["max-tokens"], "max-tokens", 1024, 32768) }),
    }, timeoutMs);
    const body = await json(response);
    const text = body?.choices?.[0]?.message?.content;
    const answer = Array.isArray(text) ? text.map((part) => part?.text ?? "").join("") : text;
    if (typeof answer !== "string") fail(EXIT.unavailable, "The provider returned no text.");
    process.stdout.write(redact(answer.trim()) + "\n");
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

// Explore mode. BootAgent does not know how the model is called, so the Agent
// composes the request. The script still owns the key: it adds it in the way
// --auth names, sends only to the origin of the Provider's base URL, and never
// follows a redirect with it.

const EXPLORE_METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE"];
const EXPLORE_FLAGS = ["_", "method", "path", "json", "form", "file", "query", "header", "auth", "out", "timeout"];
// Headers that carry credentials. The key goes only where --auth puts it.
const CREDENTIAL_HEADERS = new Set(["authorization", "proxy-authorization", "cookie", "x-api-key", "api-key", "host"]);
const TEXT_LIMIT = 64 * 1024;
const NOTES_LIMIT = 64 * 1024;
const MEDIA_EXTENSIONS = {
  "image/png": ".png", "image/jpeg": ".jpg", "image/webp": ".webp", "image/gif": ".gif",
  "audio/mpeg": ".mp3", "audio/mp3": ".mp3", "audio/wav": ".wav", "audio/x-wav": ".wav", "audio/wave": ".wav",
  "audio/flac": ".flac", "audio/ogg": ".ogg", "audio/opus": ".opus", "audio/aac": ".aac",
  "video/mp4": ".mp4", "video/webm": ".webm", "application/pdf": ".pdf",
};

function pair(value, flag) {
  const eq = value.indexOf("=");
  if (eq < 1) fail(EXIT.usage, `--${flag} must be name=value.`);
  return [value.slice(0, eq), value.slice(eq + 1)];
}

function providerOrigin(config) {
  return new URL(config.base_url).origin;
}

function exploreURL(config, options) {
  const origin = providerOrigin(config);
  const path = options.path ?? "";
  // A leading "//" or "/\\" would name another host; the origin check below
  // catches anything else that resolves away from the Provider.
  if (!/^\/(?![/\\])/.test(path) || /[\s\\]/.test(path)) fail(EXIT.usage, `Give the --path on ${origin}, starting with a single /.`);
  let url;
  try {
    url = new URL(path, origin + "/");
  } catch {
    fail(EXIT.usage, `--path is not a valid path: ${path}`);
  }
  if (url.origin !== origin) fail(EXIT.usage, `--path must stay on ${origin}.`);
  url.hash = "";
  for (const value of options.query ?? []) {
    const [name, item] = pair(value, "query");
    url.searchParams.append(name, item);
  }
  return url;
}

function exploreAuth(spec, key) {
  const value = spec ?? "bearer";
  if (value === "bearer") return { name: "authorization", headers: { Authorization: `Bearer ${key}` } };
  if (value === "none") return { name: "", headers: {} };
  const match = /^header:([A-Za-z0-9-]{1,64})$/.exec(value);
  if (!match || ["cookie", "host", "proxy-authorization"].includes(match[1].toLowerCase())) fail(EXIT.usage, "--auth must be bearer, none or header:<Name>.");
  return { name: match[1].toLowerCase(), headers: { [match[1]]: key } };
}

function exploreBody(options, headers, method) {
  const form = options.form ?? [];
  const files = options.file ?? [];
  if (options.json !== undefined && (form.length || files.length)) fail(EXIT.usage, "Use --json or --form and --file, not both.");
  let body;
  if (options.json !== undefined) {
    const data = readInput(options.json, LIMITS.download, "JSON body");
    try {
      JSON.parse(data.toString("utf8"));
    } catch {
      fail(EXIT.usage, `${options.json} is not valid JSON.`);
    }
    if (!Object.keys(headers).some((name) => name.toLowerCase() === "content-type")) headers["Content-Type"] = "application/json";
    body = data;
  } else if (form.length || files.length) {
    body = new FormData();
    for (const value of form) body.append(...pair(value, "form"));
    for (const value of files) {
      const [name, path] = pair(value, "file");
      body.append(name, new Blob([readInput(path, LIMITS.download, "File")]), basename(path));
    }
  }
  if (body !== undefined && method === "GET") fail(EXIT.usage, "A GET request cannot have a body.");
  return body;
}

function sniffExtension(data) {
  const head = data.subarray(0, 12);
  const text = (from, to) => head.subarray(from, to).toString("latin1");
  if (head.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return ".png";
  if (head[0] === 0xff && head[1] === 0xd8) return ".jpg";
  if (text(0, 4) === "RIFF" && text(8, 12) === "WEBP") return ".webp";
  if (text(0, 4) === "RIFF" && text(8, 12) === "WAVE") return ".wav";
  if (text(0, 3) === "GIF") return ".gif";
  if (text(0, 3) === "ID3" || (head[0] === 0xff && (head[1] & 0xe0) === 0xe0)) return ".mp3";
  if (text(4, 8) === "ftyp") return ".mp4";
  if (text(0, 4) === "fLaC") return ".flac";
  if (text(0, 4) === "OggS") return ".ogg";
  if (head.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]))) return ".webm";
  return "";
}

// Media inside a JSON response (base64, a data URL or hex) is saved as a file
// and replaced by its path, so the Agent never reads megabytes of encoded
// data. Only data that sniffs as media is taken; any other long string stays.
function extractMedia(value, save) {
  if (typeof value === "string") {
    if (value.length < 1024) return value;
    const dataURL = /^data:([a-z]+\/[a-z0-9.+-]+)?(?:;[^,;]*)*;base64,/i.exec(value);
    const candidates = [];
    if (dataURL) candidates.push([Buffer.from(value.slice(dataURL[0].length), "base64"), dataURL[1] ? MEDIA_EXTENSIONS[dataURL[1].toLowerCase()] : ""]);
    else {
      if (/^[0-9a-fA-F]+$/.test(value) && value.length % 2 === 0) candidates.push([Buffer.from(value, "hex"), ""]);
      if (/^[A-Za-z0-9+/\s]+={0,2}$/.test(value)) candidates.push([Buffer.from(value, "base64"), ""]);
    }
    for (const [data, declared] of candidates) {
      const extension = declared || sniffExtension(data);
      if (data.length && extension) return `[saved to ${save(data, extension)}]`;
    }
    return value;
  }
  if (Array.isArray(value)) return value.map((item) => extractMedia(item, save));
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([name, item]) => [name, extractMedia(item, save)]));
  return value;
}

async function readLimited(response, limit) {
  if (!response.body) return Buffer.alloc(0);
  const chunks = [];
  let size = 0;
  for await (const chunk of Readable.fromWeb(response.body)) {
    size += chunk.length;
    if (size > limit) fail(EXIT.unavailable, "The response is larger than expected and was not read.");
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

function printText(text) {
  const clean = redact(text);
  const shown = clean.length > TEXT_LIMIT ? `${clean.slice(0, TEXT_LIMIT)}\n… ${clean.length - TEXT_LIMIT} more characters not shown` : clean;
  process.stdout.write(shown.replace(/\n?$/, "\n"));
}

async function exploreRequest(config, key, options, timeoutMs) {
  for (const flag of Object.keys(options)) {
    if (!EXPLORE_FLAGS.includes(flag)) fail(EXIT.usage, `Unknown option --${flag}.`);
  }
  const method = (options.method ?? "POST").toUpperCase();
  if (!EXPLORE_METHODS.includes(method)) fail(EXIT.usage, `--method must be one of ${EXPLORE_METHODS.join(", ")}.`);
  const url = exploreURL(config, options);
  const auth = exploreAuth(options.auth, key);
  const headers = {};
  for (const value of options.header ?? []) {
    const [name, item] = pair(value, "header");
    const lower = name.toLowerCase();
    if (!/^[A-Za-z0-9-]{1,64}$/.test(name) || CREDENTIAL_HEADERS.has(lower) || lower === auth.name) {
      fail(EXIT.usage, `--header ${name} is not allowed. The key is sent with --auth.`);
    }
    headers[name] = item;
  }
  const body = exploreBody(options, headers, method);
  let response;
  try {
    // No redirect is followed: it could carry the key to another host.
    response = await fetch(url, { method, headers: { ...headers, ...auth.headers }, body, redirect: "manual", signal: AbortSignal.timeout(timeoutMs) });
  } catch (error) {
    if (error?.name === "TimeoutError" || error?.name === "AbortError") fail(EXIT.unavailable, `The provider did not answer within ${Math.round(timeoutMs / 1000)} s.`);
    fail(EXIT.unavailable, `Cannot reach the provider: ${redact(error?.cause?.code ?? error?.message ?? error)}`);
  }
  const type = (response.headers.get("content-type") ?? "").toLowerCase();
  process.stdout.write(`HTTP ${response.status} ${type || "(no content type)"}\n`);
  if (response.status >= 300 && response.status < 400) {
    const location = response.headers.get("location");
    if (location) process.stdout.write(redact(`Location: ${location}`) + "\n");
    fail(EXIT.refused, "The provider answered with a redirect, which is not followed. If it points at a result file, download it with fetch-result.");
  }
  const directory = outputDirectory(config, options);
  const textual = !type || /json|^text\/|xml|javascript|x-www-form-urlencoded/.test(type);
  if (!textual && response.ok) {
    const saved = await saveStream(response.body, join(directory, `response-${stamp()}${MEDIA_EXTENSIONS[type.split(";")[0].trim()] ?? ".bin"}`), LIMITS.video);
    process.stdout.write(`[saved to ${saved}]\n`);
  } else {
    const data = await readLimited(response, LIMITS.response);
    let parsed;
    try {
      parsed = JSON.parse(data.toString("utf8"));
    } catch {
      parsed = undefined;
    }
    if (parsed !== undefined) {
      let count = 0;
      const save = (bytes, extension) => writeOutput(join(directory, `response-${stamp()}-${++count}${extension}`), bytes);
      printText(JSON.stringify(response.ok ? extractMedia(parsed, save) : parsed, null, 2));
    } else if (data.includes(0)) {
      if (response.ok) process.stdout.write(`[saved to ${writeOutput(join(directory, `response-${stamp()}${sniffExtension(data) || ".bin"}`), data)}]\n`);
    } else {
      printText(data.toString("utf8"));
    }
  }
  if (response.ok) return;
  if (response.status === 401 || response.status === 403) fail(EXIT.key, `The provider rejected the key or the way it was sent (HTTP ${response.status}). Check --auth against the documentation before asking the user about the key.`);
  if (response.status === 408 || response.status === 429 || response.status >= 500) fail(EXIT.unavailable, `The provider is busy or failing (HTTP ${response.status}).`);
  fail(EXIT.refused, `The provider refused the request (HTTP ${response.status}).`);
}

// Result URLs are usually pre-signed on another host, so the key is never sent.
async function fetchResult(config, key, options, timeoutMs) {
  if (!options.url) fail(EXIT.usage, "Give the --url to download.");
  let url;
  try {
    url = new URL(options.url);
  } catch {
    fail(EXIT.usage, "--url is not a valid URL.");
  }
  if (url.username || url.password) fail(EXIT.usage, "--url must not carry credentials.");
  if (url.protocol !== "https:" && url.origin !== providerOrigin(config)) fail(EXIT.usage, "--url must use https.");
  let response;
  try {
    response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
  } catch {
    fail(EXIT.unavailable, "Cannot download the result.");
  }
  if (!response.ok || !response.body) fail(EXIT.unavailable, `Cannot download the result (HTTP ${response.status}).`);
  const type = (response.headers.get("content-type") ?? "").toLowerCase();
  const fromPath = extname(url.pathname).toLowerCase();
  const extension = /^\.[a-z0-9]{1,5}$/.test(fromPath) ? fromPath : MEDIA_EXTENSIONS[type.split(";")[0].trim()] ?? ".bin";
  process.stdout.write(await saveStream(response.body, join(outputDirectory(config, options), `result-${stamp()}${extension}`), LIMITS.video) + "\n");
}

// The notes live outside the Skill tree, so recording them never makes the
// managed tree look edited, and they survive a reinstall.
function notesPath(config) {
  if (typeof config.notes_file !== "string" || !config.notes_file) fail(EXIT.setup, "config.json has no notes_file. Reinstall the Skill from BootAgent.");
  return resolve(expandHome(config.notes_file));
}

async function showNotes(config) {
  const path = notesPath(config);
  if (!existsSync(path)) {
    process.stdout.write("No notes yet. Work the request out with the user before the first run.\n");
    return;
  }
  printText(readFileSync(path, "utf8"));
}

async function saveNotes(config, key, options) {
  if (!options.from) fail(EXIT.usage, "Give the file holding the notes with --from.");
  const text = readInput(options.from, NOTES_LIMIT, "Notes").toString("utf8");
  if (text.includes("\0")) fail(EXIT.usage, "The notes must be text.");
  // A key that slipped into the notes is removed rather than stored.
  const clean = redact(text).replace(/\bsk-[A-Za-z0-9_-]{16,}/g, "[redacted]");
  const path = notesPath(config);
  mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
  const temporary = `${path}.${process.pid}.tmp`;
  writeFileSync(temporary, clean.replace(/\n?$/, "\n"), { mode: 0o600 });
  renameSync(temporary, path);
  process.stdout.write(`Saved notes to ${path}\n`);
}

// Explore serves every capability, so it is looked up by adapter alone. Its
// helpers need no key, but read it when present so their output is redacted.
const EXPLORE = {
  name: "request",
  run: exploreRequest,
  timeout: 300,
  extra: { "fetch-result": fetchResult, notes: showNotes, "save-notes": saveNotes },
  keyless: ["fetch-result", "notes", "save-notes"],
};

const COMMANDS = {
  "vision/openai-chat-vision": { name: "describe", run: describe, timeout: 120 },
  "image-generation/openai-images": { name: "generate", run: generate, timeout: 300 },
  "speech-to-text/openai-audio-transcriptions": { name: "transcribe", run: transcribe, timeout: 300 },
  "text-to-speech/openai-audio-speech": { name: "speak", run: speak, timeout: 120 },
  "text-to-speech/novita-audio": { name: "speak", run: speakNative, timeout: 120 },
  "video-generation/novita-async": { name: "video", run: generateVideo, timeout: 600, extra: { "video-result": videoResult } },
  "video-understanding/frames-chat-vision": { name: "describe-video", run: describeVideo, timeout: 300 },
};

async function main() {
  const [major] = process.versions.node.split(".").map(Number);
  if (!(major >= 18) || typeof fetch !== "function" || typeof FormData !== "function") {
    fail(EXIT.setup, `Node.js 18 or later is required; this is ${process.versions.node}.`);
  }
  const config = loadConfig();
  const command = config.adapter === "explore" ? EXPLORE : COMMANDS[`${config.capability}/${config.adapter}`];
  if (!command) {
    fail(EXIT.setup, `This version of the script cannot run ${config.capability} over ${config.adapter}. Reinstall the Skill from BootAgent.`);
  }
  const [subcommand, ...rest] = process.argv.slice(2);
  if (!subcommand || subcommand === "--help" || subcommand === "help") {
    const extra = Object.keys(command.extra ?? {}).map((name) => `       node scripts/run.mjs ${name} [options]\n`).join("");
    process.stdout.write(`Usage: node scripts/run.mjs ${command.name} [options]\n${extra}       node scripts/run.mjs check\nSee SKILL.md for the options and exit codes.\n`);
    return;
  }
  if (subcommand === "check") {
    loadKey(config);
    process.stdout.write(`ready: ${config.capability} with ${config.model}\n`);
    return;
  }
  const run = subcommand === command.name ? command.run : command.extra?.[subcommand];
  if (!run) fail(EXIT.usage, `This Skill runs "${command.name}", not "${subcommand}".`);
  const options = parseArgs(rest);
  if (options._.length) fail(EXIT.usage, `Unexpected argument: ${options._[0]}`);
  const timeout = positiveInt(options.timeout, "timeout", command.timeout, 7200) * 1000;
  let key = "";
  if (command.keyless?.includes(subcommand)) {
    try {
      key = loadKey(config);
    } catch {
      key = "";
    }
  } else key = loadKey(config);
  await run(config, key, options, timeout);
}

main().then(
  () => { process.exitCode = EXIT.ok; },
  (error) => {
    const code = error instanceof Failure ? error.code : EXIT.internal;
    process.stderr.write(redact(error instanceof Failure ? error.message : `Unexpected error: ${error?.message ?? error}`) + "\n");
    process.exitCode = code;
  },
);
